class Solution { public int checkRecord(int n) { long MOD = 1000000007; long[][] dp = new long[2][3]; dp[0][0] = 1; for (int i = 0; i < n; i++) { long[][] next = new long[2][3]; for (int a = 0; a < 2; a++) { for (int l = 0; l < 3; l++) { if (dp[a][l] == 0) continue; next[a][0] = (next[a][0] + dp[a][l]) % MOD; if (a + 1 < 2) { next[a + 1][0] = (next[a + 1][0] + dp[a][l]) % MOD; } if (l + 1 < 3) { next[a][l + 1] = (next[a][l + 1] + dp[a][l]) % MOD; } } } dp = next; } long ans = 0; for (int a = 0; a < 2; a++) { for (int l = 0; l < 3; l++) { ans = (ans + dp[a][l]) % MOD; } } return (int) ans; } }